DROP TABLE IF EXISTS `after_sales_ticket`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `after_sales_ticket` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '提交用户',
  `registration_id` bigint DEFAULT NULL COMMENT '关联报名记录',
  `title` varchar(200) NOT NULL COMMENT '工单标题',
  `content` text NOT NULL COMMENT '问题描述',
  `type` varchar(50) DEFAULT NULL COMMENT '类型：refund退款/consult咨询/complaint投诉/other其他',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待处理 1处理中 2已解决 3已关闭',
  `reply` text COMMENT '回复内容',
  `replied_by` bigint DEFAULT NULL COMMENT '回复人',
  `replied_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ticket_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
