INSERT INTO `after_sales_ticket` VALUES (1,1,NULL,'测试咨询工单','请问考试成绩什么时候发布？','consult',2,'您好，您的问题已收到，我们会尽快处理。',1,'2026-09-17 20:00:38','2026-09-17 19:54:25','2026-09-17 20:00:38'),(28,101,NULL,'如何修改报名信息','报名时工作单位填写有误，现需要修改为单位最新名称，请问如何操作？','consult',1,NULL,NULL,NULL,'2026-09-19 14:49:08','2026-09-19 15:06:08'),(29,102,NULL,'成绩复核申请咨询','本人的实操成绩与预期差距较大，申请成绩复核并说明复核流程。','consult',2,'已收到您的复核申请，复核结果将在10个工作日内通过站内消息和邮件反馈。',1,'2026-09-19 14:44:08','2026-09-19 14:32:08','2026-09-19 15:06:08'),(30,103,NULL,'证书发放进度咨询','证书显示已发放但尚未收到邮寄，想咨询当前发放进度。','consult',3,'证书已交由邮政EMS寄出，单号将发送至您的邮箱，请注意查收。',1,'2026-09-19 14:33:08','2026-09-19 14:15:08','2026-09-19 15:06:08'),(31,104,NULL,'考试当天时间冲突申诉','考试时间与单位安排的出差时间冲突，申请协调其他批次或延期参考。','complaint',0,NULL,NULL,NULL,'2026-09-19 13:58:08','2026-09-19 15:06:08'),(32,105,NULL,'申请退还考试费用','本人因工作调动无法按时参加考试，申请退还已缴纳的考试费用，望审核处理。','refund',1,NULL,NULL,NULL,'2026-09-19 13:41:08','2026-09-19 15:06:08'),(33,106,NULL,'如何修改报名信息','报名时工作单位填写有误，现需要修改为单位最新名称，请问如何操作？','consult',2,'您好，请携带单位证明材料到鉴定中心前台办理信息变更，或联系客服协助线上修改。',1,'2026-09-19 14:00:08','2026-09-19 13:24:08','2026-09-19 15:06:08'),(34,107,NULL,'成绩复核申请咨询','本人的实操成绩与预期差距较大，申请成绩复核并说明复核流程。','consult',3,'已收到您的复核申请，复核结果将在10个工作日内通过站内消息和邮件反馈。',1,'2026-09-19 13:49:08','2026-09-19 13:07:08','2026-09-19 15:06:08'),(35,108,NULL,'证书发放进度咨询','证书显示已发放但尚未收到邮寄，想咨询当前发放进度。','consult',0,NULL,NULL,NULL,'2026-09-19 12:50:08','2026-09-19 15:06:08'),(36,109,NULL,'考试当天时间冲突申诉','考试时间与单位安排的出差时间冲突，申请协调其他批次或延期参考。','complaint',1,NULL,NULL,NULL,'2026-09-19 12:33:08','2026-09-19 15:06:08'),(37,110,NULL,'申请退还考试费用','本人因工作调动无法按时参加考试，申请退还已缴纳的考试费用，望审核处理。','refund',2,'经核实符合退费条件，费用将在3个工作日内原路退回，请注意查收。',1,'2026-09-19 13:16:08','2026-09-19 12:16:08','2026-09-19 15:06:08'),(38,111,NULL,'如何修改报名信息','报名时工作单位填写有误，现需要修改为单位最新名称，请问如何操作？','consult',3,'您好，请携带单位证明材料到鉴定中心前台办理信息变更，或联系客服协助线上修改。',1,'2026-09-19 13:05:08','2026-09-19 11:59:08','2026-09-19 15:06:08'),(39,112,NULL,'成绩复核申请咨询','本人的实操成绩与预期差距较大，申请成绩复核并说明复核流程。','consult',0,NULL,NULL,NULL,'2026-09-19 11:42:08','2026-0