INSERT INTO `ai_qa_log` VALUES (1,NULL,'报名条件是什么','报名条件通常包括：1）年满16周岁；2）身体健康，能正常参加考试；3）具备相应职业技能基础或相关工作经历。具体条件以各考试计划公布的为准，您可在首页「考试计划」中查看详情。','报名咨询','2026-09-17 19:39:19'),(2,NULL,'如何缴费？','缴费流程：审核通过后，登录个人中心→我的报名→点击「缴费」按钮，支持微信支付和支付宝。缴费成功后不可退款，请确认信息无误后再支付。','缴费问题','2026-09-17 20:00:16'),(3,NULL,'证书如何领取？','考试合格后，系统自动生成电子证书，您可在个人中心→我的证书中查看和打印。纸质证书将在考后30个工作日内邮寄到报名时填写的地址。证书可在首页「证书查验」中输入编号核验真伪。','证书相关','2026-09-17 20:04:30'),(4,NULL,'报名条件是什么？','报名条件通常包括：1）年满16周岁；2）身体健康，能正常参加考试；3）具备相应职业技能基础或相关工作经历。具体条件以各考试计划公布的为准，您可在首页「考试计划」中查看详情。','报名咨询','2026-09-17 21:15:51'),(5,NULL,'你是谁','感谢您的咨询！关于「你是谁」，建议您：1）查看首页「常见问题」栏目；2）浏览对应考试计划的详情说明；3）如仍有疑问，请拨打咨询电话400-000-2026或通过公众号留言，我们会尽快为您解答。','通用咨询','2026-09-17 21:15:57'),(6,NULL,'证书如何领取？','考试合格后，系统自动生成电子证书，您可在个人中心→我的证书中查看和打印。纸质证书将在考后30个工作日内邮寄到报名时填写的地址。证书可在首页「证书查验」中输入编号核验真伪。','证书相关','2026-09-17 21:16:06'),(7,NULL,'有性价比吗','感谢您的咨询！关于「有性价比吗」，建议您：1）查看首页「常见问题」栏目；2）浏览对应考试计划的详情说明；3）如仍有疑问，请拨打咨询电话400-000-2026或通过公众号留言，我们会尽快为您解答。','通用咨询','2026-09-17 21:16:18'),(8,NULL,'如何缴费？','缴费流程：审核通过后，登录个人中心→我的报名→点击「缴费」按钮，支持微信支付和支付宝。缴费成功后不可退款，请确认信息无误后再支付。','缴费问题','2026-09-18 15:01:05'),(9,NULL,'证书如何领取？','考试合格后，系统自动生成电子证书，您可在个人中心→我的证书中查看和打印。纸质证书将在考后30个工作日内邮寄到报名时填写的地址。证书可在首页「证书查验」中输入编号核验真伪。','证书相关','2026-09-18 15:01:07'),(10,NULL,'准考证什么时候打印？','考务人员完成考场编排后，系统会自动生成准考证。您可在个人中心→准考证打印中查看考场、座位号并打印准考证。请提前30分钟到达考场，携带有效身份证件。','考场安排','2026-09-18 15:01:08'),(11,NULL,'报名条件是什么？','报名条件通常包括：1）年满16周岁；2）身体健康，能正常参加考试；3）具备相应职业技能基础或相关工作经历。具体条件以各考试计划公布的为准，您可在首页「考试计划」中查看详情。','报名咨询','2026-09-18 15:01:09'),(12,NULL,'?????','感谢您的咨询！关于「?????」，建议您：1）查看首页「常见问题」栏目；2）浏览对应考试计划的详情说明；3）如仍有疑问，请拨打咨询电话400-000-2026或通过公众号留言，我们会尽快为您解答。','通用咨询','2026-09-19 09:57:48'),(73,101,'支持哪些缴费方式？','目前支持微信支付、支付宝和银行转账三种方式，缴费成功后报名状态将实时更新为\"已缴费\"。','payment','2026-09-19 14:05:07'),(74,102,'考场和座位是怎么分配的？','系统根据您报考的计划自动编排考场与座位，编排完成后可在个人中心查看准考证号、考场地点及座位号。','exam_venue','2026-09-19 13:04:07'),(75,103,'成绩什么时候公布？在哪里查询？','考试结束后约10个工作日公布成绩，届时可在个人中心\"我的成绩\"页面查询理论和实操成绩及综合评定结果。','results','2026-09-19 12:03:07'),(76,104,'证书如何领取？多久能拿到？','成绩合格后，电子证书可在个人中心直接查看和下载，纸质证书将于考后30个工作日内制作并邮寄发放。','certificate','2026-09-19 11:02:07'),(77,105,'忘记密码怎么办？','可在登录页点击\"忘记密码\"，通过注册邮箱获取验证码重置密码；也可使用注册时生成的16位账号恢复令牌找回。','password','2026-09-19 10:01:07'),(78,106,'报名需要准备哪些材料？','报名需准备：本人身份证正反面照片、学历证明、工作年限证明（按报考条件）、近期免冠证件照。请在上传材料页依次上传，单个文件不超过10MB，支持JPG/PNG/PDF格式。','registration','2026-09-19 09:00:07'),(79,107,'支持哪些缴费方式？','目前支持微信支付、支付宝和银行转账三种方式，缴费成功后报名状态将实时更新为\"已缴费\"。','payment','2026-09-19 07:59:07'),(80,108,'考场和座位是怎么分配的？','系统根据您报考的计划自动编排考场与座位，编排完成后可在个人中心查看准考证号、考场地点及座位号。','exam_venue','2026-09-19 06:58:07'),(81,109,'成绩什么时候公布？在哪里查询？','考试结束后约10个工作日公布成绩，届时可在个人中心\"我的成绩\"页面查询理论和实操成绩及综合评定结果。','results','2026-09-19 05:57:07'),(82,110,'证书如何领取？多久能拿到？','成绩合格后，电子证书可在个人中心直接查看和下载，纸质证书将于考后30个工作日内制作并邮寄发放。','certificate','2026-09-19 04:56:07'),(83,111,'忘记密码怎么办？','可在登录页点击\"忘记密码\"，通过注册邮箱获取验证码重置密码；也可使用注册时生成的16位账号恢复令牌找回。','password','2026-09-19 03:55:07'),(84,112,'报名需要准备哪些材料？','报名需准备：本人身份证正反面照片、学历证明、工作年限证明（按报考条件）、近期免冠证件照。请在上传材料页依次上传，单个文件不超过10MB，支持JPG/PNG/PDF格式。','registration','2026-09-19 02:54:07'),(85,113,'支持哪些缴费方式？','目前支持微信支付、支付宝和银行转账三种方式，缴费成功后报名状态将实时更新为\"已缴费\"。','payment','2026-09-19 01:53:07'),(86,114,'考场和座位是怎么分配的？','系统根据您报考的计划自动编排考场与座位，编排完成后可在个人中心查看准考证号、考场地点及座位号。','exam_venue','2026-09-19 00:52:07'),(87,115,'成绩什么时候公布？在哪里查询？','考试结束后约10个工作日公布成绩，届时可在个人中心\"我的成绩\"页面查询理论和实操成绩及综合评定结果。','results','2026-09-18 23:51:07'),(88,116,'证书如何领取？多久能拿到？','成绩合格后，电子证书可在个人中心直接查看和下载，纸质证书将于考后30个工作日内制作并邮寄发放。','certificate','2026-09-18 22:50:07'),(89,117,'忘记密码怎么办？','可在登录页点击\"忘记密码\"，通过注册邮箱获取验证码重置密码；也可使用注册时生成的16位账号恢复令牌找回。','password','2026-09-18 21:49:07'),(90,118,'报名需要准备哪些材料？','报名需准备：本人身份证正反面照片、学历证明、工作年限证明（按报考条件）、近期免冠证件照。请在上传材料页依次上传，单个文件不超过10MB，支持JPG/PNG/PDF格式。','registration','2026-09-18 20:48:07'),(91,119,'支持哪些缴费方式？','目前支持微信支付、支付宝和银行转账三种方式，缴费成功后报名状态将实时更新为\"已缴费\"。','payment','2026-09-18 19:47:07'),(92,120,'考场和座位是怎么分配的？','系统根据您报考的计划自动编排考场与座位，编排完成后可在个人中心查看准考证号、考场地点及座位号。','exam_venue','2026-09-18 18:46:07'),(93,121,'成绩什么时候公布？在哪里查询？','考试结束后约10个工作日公布成绩，届时可在个人中心\"我的成绩\"页面查询理论和