INSERT INTO `announcement` VALUES (1,'2026年度职业技能等级认定报名公告','为方便考生报名，现开放电工、焊工、钳工等职业技能等级认定考试计划，请考生及时关注报名时间。',1,1,3,'2026-09-15 19:04:39','2026-09-15 19:04:39'),(2,'考生报名材料上传须知','请上传清晰有效的身份证明、学历或工作经历材料，单个文件不超过10MB，支持JPG/PNG/PDF格式。',0,1,3,'2026-09-15 19:04:39','2026-09-15 19:04:39'),(3,'准考证打印及考场纪律提醒','准考证生成后请及时核对个人信息，考试当天须携带有效身份证件及准考证参加考试。',0,1,3,'2026-09-15 19:04:39','2026-09-15 19:04:39'),(4,'2026年第四季度考试计划已发布','本季度新增美容师、茶艺师、育婴员、养老护理员等20余个职业的技能认定计划，欢迎广大考生报名。',1,1,3,'2026-09-17 20:02:23','2026-09-17 20:02:23'),(5,'关于考试收费标准的通知','根据相关规定，各职业技能等级认定考试收费标准已公示，请考生在报名页面查看具体费用。',0,1,3,'2026-09-15 20:34:13','2026-09-15 20:34:13'),(6,'疫情防控期间考试安排说明','考试期间请考生配合做好体温检测、佩戴口罩等防疫措施，具体要求以考点公告为准。',0,1,3,'2026-09-15 20:34:13','2026-09-15 20:34:13'),(7,'技能等级证书查询方式','考试合格后，考生可在个人中心查询电子证书，纸质证书将在考后30个工作日内发放。',0,1,3,'2026-09-15 20:34:13','2026-09-15 20:34:13'),(8,'测试导入公告A','导入内容A',0,1,1,'2026-09-17 20:04:16','2026-09-17 20:04:16'),(9,'测试导入公告B','导入内容B',1,1,1,'2026-09-17 20:04:16','2026-09-17 20:04:16'),(10,'手动新增测试公告','手动新增内容',1,1,1,'2026-09-17 20:04:16','2026-09-17 20:04:16');
