DROP TABLE IF EXISTS `payment_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `registration_id` bigint NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `pay_method` varchar(50) DEFAULT NULL COMMENT 'wechat/alipay/bank',
  `trade_no` varchar(100) DEFAULT NULL,
  `pay_status` tinyint NOT NULL DEFAULT '0' COMMENT '0待支付 1已支付 2已退款',
  `paid_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_payment_reg` (`registration_id`)
) ENGINE=InnoDB AUTO_INCREMENT=664 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

