--
-- Table structure for table `sys_user`
--

DROP TABLE IF EXISTS `sys_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL COMMENT '用户名',
  `password` varchar(128) NOT NULL COMMENT 'BCrypt密码',
  `real_name` varchar(50) NOT NULL COMMENT '真实姓名',
  `id_card` varchar(18) NOT NULL COMMENT '身份证号',
  `phone` varchar(11) NOT NULL COMMENT '手机号',
  `email` varchar(100) DEFAULT NULL COMMENT '电子邮箱',
  `recovery_token` varchar(64) DEFAULT NULL COMMENT '账号恢复令牌',
  `gender` tinyint DEFAULT NULL COMMENT '性别 0女1男',
  `work_unit` varchar(100) DEFAULT NULL COMMENT '工作单位',
  `avatar_url` varchar(255) DEFAULT NULL,
  `role` tinyint NOT NULL DEFAULT '0' COMMENT '0考生 1管理员 2考务 3超管',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '0禁用 1启用',
  `must_change_pwd` tinyint NOT NULL DEFAULT '0',
  `login_fail_count` int NOT NULL DEFAULT '0',
  `lock_until` datetime DEFAULT NULL,
  `last_login_time` datetime DEFAULT NULL,
  `last_login_ip` varchar(50) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `age` int DEFAULT NULL COMMENT '年龄',
  `occupation` varchar(100) DEFAULT NULL COMMENT '职业',
  `income_range` varchar(50) DEFAULT NULL COMMENT '收入范围',
  `region` varchar(100) DEFAULT NULL COMMENT '所在地区',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `id_card` (`id_card`),
  UNIQUE KEY `phone` (`phone`)
) ENGINE=InnoDB AUTO_INCREMENT=412 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

